    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    n = len(pts)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            a, b = pts[i], pts[j]
            edges.append((abs(a[0]-b[0]) + abs(a[1]-b[1]), i, j))
    edges.sort()

    chosen = []
    for _, i, j in edges:
        a, b = find(i), find(j)
        if a != b:
            parent[a] = b
            chosen.append((i, j))

    out = [row[:] for row in grid]
    for i, j in chosen:
        (r1, c1), (r2, c2) = pts[i], pts[j]
        # Route along the row of an endpoint, then along the column.
        corner = (r1, c2)
        for r, c in ((r1, c1), (r2, c2)):
            pass
        r, c = r1, c1
        while c != corner[1]:
            c += 1 if corner[1] > c else -1
